String _lowercaseFirstAsciiLetter(String text) {
  final trimmed = text.trim();
  if (trimmed.isEmpty) return trimmed;
  final first = trimmed.codeUnitAt(0);
  if (first >= 65 && first <= 90) {
    return '${String.fromCharCode(first + 32)}${trimmed.substring(1)}';
  }
  return trimmed;
}

